void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    float temp = 0.6; //temprature value from -1.0(coolest) to 1.0 (warmest)
    vec3 warm_color = vec3(1.0, 0.5, 0.31); //orangish color
    vec3 cool_color = vec3(0.3, 0.6, 1.0); //blueish color

    float warm = max(temp, 0.0);
    float cold = max(-temp, 0.0);
    vec3 sampled_tex = texture(iChannel0, uv).rgb;

//    float lum = (sampled_tex.x + sampled_tex.y + sampled_tex.z) / 3.0; //maybe used

    vec3 color = sampled_tex;
    color = mix(color, color * warm_color, warm);
    color = mix(color, color * cool_color, cold);

    fragColor = vec4(color, 1.0);
}
